122	export interface Damage {
123	  itemType: string;
124	  amount: number;
125	}
126	
127	export interface Incident {
128	  cause: string;
129	  damages: Damage[];
130	}
131	
132	export interface ClaimResult {
133	  payout: number;
134	  remainingCap: number;
135	}
136	
137	const DEDUCTIBLE = 100;
138	const CAP_MULTIPLIER = 2;
139	
140	const INSURANCE_VALUES: Record<string, number> = {
141	  sword: 1000,
142	  amulet: 600,
143	  staff: 800,
144	  potion: 400,
145	  rune: 250,
146	  moonstone: 250,
147	};
148	
149	const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type] ?? 0;
150	
151	const insuranceSum = (items: Item[]): number =>
152	  items.reduce((sum, item) => sum + insuranceValue(item), 0);
153	
154	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
155	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
156	
157	const reimbursedAmount = (item: Item, amount: number): number =>
158	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
159	    ? percentOf(amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
160	    : amount;
161	
162	const damagePayout = (damage: Damage, item: Item): number =>
163	  Math.max(0, reimbursedAmount(item, damage.amount) - DEDUCTIBLE);
164	
165	const insuredItemFor = (items: Item[], damage: Damage): Item =>
166	  items.find((item) => item.type === damage.itemType) as Item;
167	
168	const validateDamageCounts = (items: Item[], damages: Damage[]): void => {
169	  const insuredCounts = countByType(items);
170	  const damageCounts = new Map<string, number>();
171	  for (const damage of damages) {
172	    const next = (damageCounts.get(damage.itemType) ?? 0) + 1;
173	    if (next > (insuredCounts.get(damage.itemType) ?? 0)) {
174	      throw new Error(
175	        `More ${damage.itemType} damages than insured items in the policy`,
176	      );
177	    }
178	    damageCounts.set(damage.itemType, next);
179	  }
180	};
181	
182	export const claim = (
183	  items: Item[],
184	  incident: Incident,
185	  priorPayouts: number,
186	): ClaimResult => {
187	  validateDamageCounts(items, incident.damages);
188	  const cap = insuranceSum(items) * CAP_MULTIPLIER;
189	  const payout = incident.damages.reduce(
190	    (sum, damage) => sum + damagePayout(damage, insuredItemFor(items, damage)),
191	    0,
192	  );
193	  return { payout, remainingCap: cap - priorPayouts - payout };
194	};
